import React, { useState } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function App() {
  const [step, setStep] = useState(0);

  const [incomeCategory, setIncomeCategory] = useState("");
  const [questionnaire, setQuestionnaire] = useState({});
  const [spendingPriorities, setSpendingPriorities] = useState({});
  const [selectedCategories, setSelectedCategories] = useState([]); // 🔥 NEW

  const handleFinalSave = async (limits) => {
    const finalData = {
      incomeCategory,
      questionnaire,
      spendingPriority: spendingPriorities,
      budgetLimits: limits
    };

    console.log("FINAL DATA:", finalData);

    try {
      const res = await fetch("http://localhost:5000/api/userdata/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(finalData)
      });

      const data = await res.json();

      if (data.success) {
        alert("Data saved successfully!");
      } else {
        alert("Error saving data");
      }
    } catch (err) {
      console.error(err);
      alert("Server error");
    }
  };

  return (
    <>
      {step === 0 && (
        <Login onLogin={() => setStep(1)} />
      )}

      {step === 1 && (
        <IncomeCategory
          onNext={(data) => {
            setIncomeCategory(data);
            setStep(2);
          }}
        />
      )}

      {step === 2 && (
        <Questionnaire
          onNext={(data) => {
            setQuestionnaire(data);
            setStep(3);
          }}
        />
      )}

      {step === 3 && (
        <SpendingPriority
          onNext={(filteredCategories) => {
            setSelectedCategories(filteredCategories); // 🔥 categories ≥3
            setSpendingPriorities(filteredCategories);  // optional store
            setStep(4);
          }}
        />
      )}

      {step === 4 && (
        <BudgetLimits
          selectedCategories={selectedCategories} // 🔥 PASS HERE
          onNext={handleFinalSave}
        />
      )}
    </>
  );
}

export default App;
